package com.atelier.tasks.controller;
import com.atelier.tasks.dto.ApiDtos.*;import com.atelier.tasks.entity.AppUser;import com.atelier.tasks.entity.Category;import com.atelier.tasks.repository.UserRepository;import com.atelier.tasks.repository.CategoryRepository;import com.atelier.tasks.security.JwtService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.List;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final UserRepository users;private final CategoryRepository categories;private final PasswordEncoder encoder;private final JwtService jwt;
 public AuthController(UserRepository u,CategoryRepository c,PasswordEncoder e,JwtService j){users=u;categories=c;encoder=e;jwt=j;}
 public record Register(@NotBlank @Size(max=80) String name,@NotBlank @Email @Size(max=180) String email,@NotBlank @Size(min=8,max=72) String password){}
 public record Login(@NotBlank @Email String email,@NotBlank String password){}
 @PostMapping("/register") @org.springframework.transaction.annotation.Transactional public ResponseEntity<AuthView> register(@Valid @RequestBody Register request){String email=request.email().trim().toLowerCase();if(users.findByEmailIgnoreCase(email).isPresent())throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");AppUser u=new AppUser(request.name().trim(),email,encoder.encode(request.password()));try{users.saveAndFlush(u);}catch(DataIntegrityViolationException ex){throw new org.springframework.web.server.ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");}for(String name:List.of("Work","Personal","Learning","Health","Creative","Errands")){Category c=new Category();c.owner=u;c.name=name;categories.save(c);}return ResponseEntity.status(HttpStatus.CREATED).body(new AuthView(jwt.create(u.email),UserView.of(u)));}
 @PostMapping("/login") public AuthView login(@Valid @RequestBody Login request){AppUser u=users.findByEmailIgnoreCase(request.email().trim()).filter(x->encoder.matches(request.password(),x.passwordHash)).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect"));return new AuthView(jwt.create(u.email),UserView.of(u));}
 @GetMapping("/me") public UserView me(Principal principal){return users.findByEmailIgnoreCase(principal.getName()).map(UserView::of).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED));}
}
